/**
 * Shared league logic for the standings and pairing scripts.
 *
 * Layout per league (content/Leagues/<League>/):
 *   <League>.md                       league note: status, rounds, current_round, bye, winner
 *   Registered Players/<Name>.md      player notes (status: active | dropped; optional joined_round,
 *                                     default 1, for late joiners; totals written here)
 *   Pairings/Round N/<A> vs <B>.md    pairing notes (tag `pairing`): generated by the pairing script;
 *                                     status, VP and result link are kept in sync from the results
 *   Results/.../<match>.md            result notes (tag `match`): round, player_a, player_b, vp_a, vp_b,
 *                                     optional `pairing` link. One per game actually played.
 *
 * Rules:
 *   - Winner is whoever scored more VP. Draws are impossible (play continues until one side
 *     leads), so equal VP is rejected as a data error.
 *   - A closed round with no match note for a player counts as a bye: 0 VP and not a game played.
 *     Rounds before a player's joined_round are not counted at all (not byes).
 *     Closed rounds are 1..current_round when status is "Completed", otherwise 1..current_round-1.
 *   - rank: dense rank by average VP per game (e.g. 4, 4, 5, 6, 6).
 *   - rank_label: rank for display, with " - tied" when shared.
 *   - position: full order 1..n. Within a shared rank: head-to-head (wins minus losses among the
 *     tied players), then opponents' average VP, then name.
 */
import fs from "node:fs"
import path from "node:path"
import matter from "gray-matter"

export const LEAGUES_DIR = path.join(process.cwd(), "content", "Leagues")

export type Match = {
  round: number
  a: string
  b: string
  vpA: number
  vpB: number
  file: string
  /** basename of the linked pairing note, if the result names one */
  pairing?: string
}

export type Pairing = {
  round: number
  a: string
  b: string
  file: string
  data: Record<string, unknown>
}

export type Player = { name: string; file: string; dropped: boolean; joinedRound: number }

export type League = {
  name: string
  dir: string
  noteFile: string
  data: Record<string, unknown>
  players: Map<string, Player>
  matches: Match[]
  pairings: Pairing[]
  currentRound: number
  completed: boolean
}

export type Stats = {
  name: string
  file: string
  games: number
  vpTotal: number
  wins: number
  losses: number
  byes: number
  avg: number
  oppAvg: number
  rank: number
  position: number
  rankLabel: string
}

export const rel = (file: string) => path.relative(process.cwd(), file)
export const round2 = (n: number) => Math.round(n * 100) / 100

export const listDirs = (dir: string) =>
  fs.existsSync(dir)
    ? fs
        .readdirSync(dir, { withFileTypes: true })
        .filter((d) => d.isDirectory() && !d.name.startsWith("."))
        .map((d) => d.name)
    : []

const listNotes = (dir: string) =>
  fs.existsSync(dir) ? fs.readdirSync(dir).filter((f) => f.endsWith(".md")) : []

/** All .md files under dir, at any depth (paths relative to dir). */
const listNotesDeep = (dir: string): string[] =>
  fs.existsSync(dir)
    ? fs
        .readdirSync(dir, { recursive: true, encoding: "utf8" })
        .filter((f) => f.endsWith(".md") && !f.split(path.sep).some((p) => p.startsWith(".")))
    : []

/** League folders under content/Leagues (folders that contain <Name>/<Name>.md). */
export const leagueDirs = () =>
  listDirs(LEAGUES_DIR)
    .map((name) => path.join(LEAGUES_DIR, name))
    .filter((dir) => fs.existsSync(path.join(dir, `${path.basename(dir)}.md`)))

/** "[[Leagues/League 1/Registered Players/Brendon|Brendon]]" or "Brendon" -> "Brendon" */
export function playerName(link: unknown): string | undefined {
  if (typeof link !== "string" || !link.trim()) return undefined
  const m = link.trim().match(/^\[\[([^\]|#]+)(?:#[^\]|]*)?(?:\|[^\]]*)?\]\]$/)
  const target = (m ? m[1] : link).trim()
  return path.basename(target, ".md") || undefined
}

export function toNumber(value: unknown, where: string): number {
  const n = typeof value === "number" ? value : Number(value)
  if (value === null || value === undefined || value === "" || Number.isNaN(n)) {
    throw new Error(`${where}: missing or non-numeric value (${JSON.stringify(value)})`)
  }
  return n
}

export function readLeague(dir: string): League {
  const name = path.basename(dir)
  const noteFile = path.join(dir, `${name}.md`)
  if (!fs.existsSync(noteFile)) throw new Error(`${rel(noteFile)}: league note not found`)
  const data = matter(fs.readFileSync(noteFile, "utf8")).data as Record<string, unknown>
  const currentRound = toNumber(data.current_round, `${rel(noteFile)} current_round`)
  const completed = String(data.status ?? "").toLowerCase() === "completed"

  const players = new Map<string, Player>()
  const playersDir = path.join(dir, "Registered Players")
  for (const f of listNotes(playersDir)) {
    const file = path.join(playersDir, f)
    const pdata = matter(fs.readFileSync(file, "utf8")).data
    const pname = path.basename(f, ".md")
    const joinedRound =
      pdata.joined_round === undefined || pdata.joined_round === null || pdata.joined_round === ""
        ? 1
        : toNumber(pdata.joined_round, `${rel(file)} joined_round`)
    if (!Number.isInteger(joinedRound) || joinedRound < 1) {
      throw new Error(`${rel(file)}: joined_round must be a whole number from 1`)
    }
    players.set(pname, {
      name: pname,
      file,
      dropped: String(pdata.status ?? "").toLowerCase() === "dropped",
      joinedRound,
    })
  }

  const matches: Match[] = []
  const resultsDir = path.join(dir, "Results")
  for (const f of listNotesDeep(resultsDir)) {
    const file = path.join(resultsDir, f)
    const { data: m } = matter(fs.readFileSync(file, "utf8"))
    const tags: unknown[] = Array.isArray(m.tags) ? m.tags : []
    if (m.type !== "match" && !tags.includes("match")) continue
    const where = rel(file)
    const round = toNumber(m.round, `${where} round`)
    if (!Number.isInteger(round) || round < 1) throw new Error(`${where}: round must be a whole number from 1`)
    if (round > currentRound) {
      throw new Error(`${where}: round ${round} is after the league's current_round (${currentRound})`)
    }
    const a = playerName(m.player_a)
    const b = playerName(m.player_b)
    if (!a || !b) throw new Error(`${where}: player_a and player_b are both required`)
    for (const p of [a, b]) if (!players.has(p)) throw new Error(`${where}: "${p}" is not a registered player`)
    const vpA = toNumber(m.vp_a, `${where} vp_a`)
    const vpB = toNumber(m.vp_b, `${where} vp_b`)
    if (vpA === vpB) throw new Error(`${where}: VP is tied ${vpA}-${vpB}, but draws are not possible`)
    matches.push({ round, a, b, vpA, vpB, file, pairing: playerName(m.pairing) })
  }

  const pairings: Pairing[] = []
  const pairingsDir = path.join(dir, "Pairings")
  for (const f of listNotesDeep(pairingsDir)) {
    const file = path.join(pairingsDir, f)
    const { data: p } = matter(fs.readFileSync(file, "utf8"))
    const tags: unknown[] = Array.isArray(p.tags) ? p.tags : []
    if (p.type !== "pairing" && !tags.includes("pairing")) continue
    const where = rel(file)
    const round = toNumber(p.round, `${where} round`)
    const a = playerName(p.player_a)
    const b = playerName(p.player_b)
    if (!a || !b) throw new Error(`${where}: player_a and player_b are both required`)
    for (const x of [a, b]) if (!players.has(x)) throw new Error(`${where}: "${x}" is not a registered player`)
    pairings.push({ round, a, b, file, data: p })
  }

  for (const x of [...matches, ...pairings]) {
    for (const name of [x.a, x.b]) {
      const joined = players.get(name)!.joinedRound
      if (x.round < joined) {
        throw new Error(`${rel(x.file)}: round ${x.round} is before ${name} joined (joined_round ${joined})`)
      }
    }
  }

  return { name, dir, noteFile, data, players, matches, pairings, currentRound, completed }
}

/** Wikilink to a note in content/, e.g. [[Leagues/League 2/Registered Players/Ann|Ann]]. */
export function noteLink(file: string, label = path.basename(file, ".md")) {
  const target = path.relative(path.join(process.cwd(), "content"), file).replace(/\.md$/, "")
  return `[[${target.split(path.sep).join("/")}|${label}]]`
}

export type PairingState = {
  status: "scheduled" | "played" | "unplayed"
  vp_a: number | null
  vp_b: number | null
  result: string | null
}

/**
 * What a pairing note should say, given its result (if any) and whether its round is closed.
 * VP is oriented to the pairing's player_a / player_b even if the result lists them the other way.
 */
export function pairingState(
  pairing: Pick<Pairing, "a" | "b" | "round">,
  result: Pick<Match, "a" | "b" | "vpA" | "vpB" | "file"> | undefined,
  closedRounds: number,
): PairingState {
  if (result) {
    const same = result.a === pairing.a
    return {
      status: "played",
      vp_a: same ? result.vpA : result.vpB,
      vp_b: same ? result.vpB : result.vpA,
      result: noteLink(result.file),
    }
  }
  return {
    status: pairing.round <= closedRounds ? "unplayed" : "scheduled",
    vp_a: null,
    vp_b: null,
    result: null,
  }
}

/**
 * Match each result to its pairing (by its `pairing` link, else by round and players) and
 * work out every pairing note's state. Leagues without pairing notes are skipped.
 */
export function syncPairings(league: League, closedRounds?: number): { file: string; state: PairingState }[] {
  if (league.pairings.length === 0) return []
  const closed = closedRounds ?? (league.completed ? league.currentRound : league.currentRound - 1)
  const byPairing = new Map<Pairing, Match>()
  for (const m of league.matches) {
    const candidates = league.pairings.filter((p) =>
      m.pairing
        ? path.basename(p.file, ".md") === m.pairing && p.round === m.round
        : p.round === m.round && pairKey(p.a, p.b) === pairKey(m.a, m.b),
    )
    const where = rel(m.file)
    if (candidates.length === 0) throw new Error(`${where}: no pairing found for round ${m.round} ${m.a} vs ${m.b}`)
    if (candidates.length > 1) throw new Error(`${where}: matches more than one pairing`)
    const p = candidates[0]
    if (pairKey(p.a, p.b) !== pairKey(m.a, m.b)) {
      throw new Error(`${where}: players don't match its pairing ${rel(p.file)}`)
    }
    const existing = byPairing.get(p)
    if (existing) throw new Error(`${rel(p.file)}: has two results (${rel(existing.file)} and ${where})`)
    byPairing.set(p, m)
  }
  return league.pairings.map((p) => ({ file: p.file, state: pairingState(p, byPairing.get(p), closed) }))
}

export function writePairings(updates: { file: string; state: PairingState }[]) {
  for (const { file, state } of updates) writeFrontmatter(file, { ...state })
}

/**
 * Standings for a league. `closedRounds` defaults to the league's own rule
 * (all rounds when completed, otherwise every round before the current one).
 */
export function computeStandings(league: League, closedRounds?: number): Stats[] {
  const closed = closedRounds ?? (league.completed ? league.currentRound : league.currentRound - 1)
  const stats = new Map<string, Stats>()
  for (const p of league.players.values()) {
    stats.set(p.name, {
      name: p.name,
      file: p.file,
      games: 0,
      vpTotal: 0,
      wins: 0,
      losses: 0,
      byes: 0,
      avg: 0,
      oppAvg: 0,
      rank: 0,
      position: 0,
      rankLabel: "",
    })
  }

  const played = new Map<string, Set<number>>()
  const opponents = new Map<string, string[]>()
  for (const m of league.matches) {
    for (const [me, them, mine, theirs] of [
      [m.a, m.b, m.vpA, m.vpB],
      [m.b, m.a, m.vpB, m.vpA],
    ] as const) {
      const s = stats.get(me)!
      s.games++
      s.vpTotal += mine
      if (mine > theirs) s.wins++
      else s.losses++
      if (!played.has(me)) played.set(me, new Set())
      played.get(me)!.add(m.round)
      opponents.set(me, [...(opponents.get(me) ?? []), them])
    }
  }
  for (const s of stats.values()) {
    const rounds = played.get(s.name) ?? new Set<number>()
    const joined = league.players.get(s.name)!.joinedRound
    for (let r = joined; r <= closed; r++) if (!rounds.has(r)) s.byes++
    s.avg = s.games > 0 ? s.vpTotal / s.games : 0
  }
  for (const s of stats.values()) {
    const opps = opponents.get(s.name) ?? []
    s.oppAvg = opps.length ? opps.reduce((t, o) => t + stats.get(o)!.avg, 0) / opps.length : 0
  }

  const sorted = [...stats.values()].sort((x, y) => y.avg - x.avg)
  const groups: Stats[][] = []
  for (const s of sorted) {
    const last = groups[groups.length - 1]
    if (last && Math.abs(last[0].avg - s.avg) < 1e-9) last.push(s)
    else groups.push([s])
  }
  const h2h = (s: Stats, group: Stats[]) => {
    const names = new Set(group.map((g) => g.name).filter((n) => n !== s.name))
    let score = 0
    for (const m of league.matches) {
      if (m.a === s.name && names.has(m.b)) score += Math.sign(m.vpA - m.vpB)
      else if (m.b === s.name && names.has(m.a)) score += Math.sign(m.vpB - m.vpA)
    }
    return score
  }
  const ranked: Stats[] = []
  groups.forEach((group, i) => {
    const keyed = group.map((s) => ({ s, h: h2h(s, group), o: round2(s.oppAvg) }))
    keyed.sort((x, y) => y.h - x.h || y.o - x.o || x.s.name.localeCompare(y.s.name))
    for (const k of keyed) {
      k.s.rank = i + 1
      k.s.position = ranked.length + 1
      ranked.push(k.s)
    }
  })
  const sharing = new Map<number, number>()
  for (const s of ranked) sharing.set(s.rank, (sharing.get(s.rank) ?? 0) + 1)
  for (const s of ranked) s.rankLabel = sharing.get(s.rank)! > 1 ? `${s.rank} - tied` : `${s.rank}`
  return ranked
}

export function printStandings(title: string, table: Stats[]) {
  console.log(`\n${title}`)
  console.table(
    table.map((s) => ({
      rank: s.rankLabel,
      position: s.position,
      player: s.name,
      avg_vp: round2(s.avg),
      games: s.games,
      vp_total: s.vpTotal,
      "W-L": `${s.wins}-${s.losses}`,
      byes: s.byes,
      opp_avg_vp: round2(s.oppAvg),
    })),
  )
}

/** Defaults every player note should have; added only when missing (never overwritten). */
const PLAYER_DEFAULTS: Record<string, string | number> = { status: "active", joined_round: 1 }

/**
 * The round a player registering now would join from, or undefined if registration is closed.
 * Same rule as the Worker (worker/index.ts registrationRound) and the registration form:
 * `registration_open: true`, and the league is Upcoming (round 1) or Active with rounds still
 * to pair (the next round; the current round is already paired).
 */
export function registrationRound(data: Record<string, unknown>): number | undefined {
  if (String(data.registration_open).toLowerCase() !== "true") return undefined
  const status = String(data.status ?? "").toLowerCase()
  if (status === "upcoming") return 1
  if (status !== "active") return undefined
  const current = Number(data.current_round)
  const rounds = Number(data.rounds)
  if (!Number.isInteger(current) || !Number.isInteger(rounds) || current >= rounds) return undefined
  return current + 1
}

/** League-level totals written to the league note (e.g. player_count, shown on the homepage cards). */
export function writeLeagueSummary(league: League) {
  writeFrontmatter(league.noteFile, { player_count: league.players.size })
}

export function writeStandings(table: Stats[]) {
  for (const s of table) {
    const fm = matter(fs.readFileSync(s.file, "utf8")).data
    const missing = Object.fromEntries(Object.entries(PLAYER_DEFAULTS).filter(([k]) => !(k in fm)))
    if (Object.keys(missing).length) writeFrontmatter(s.file, missing)
    writeFrontmatter(s.file, {
      rank: s.rank,
      rank_label: s.rankLabel,
      position: s.position,
      avg_vp: round2(s.avg),
      games: s.games,
      vp_total: s.vpTotal,
      wins: s.wins,
      losses: s.losses,
      byes: s.byes,
      opp_avg_vp: round2(s.oppAvg),
    })
  }
}

type FrontmatterValue = number | string | null | string[] | undefined

const yamlScalar = (v: number | string | null) =>
  v === null ? "" : typeof v === "string" ? JSON.stringify(v) : String(v)

/**
 * Replace or insert top-level keys in a note's frontmatter, leaving everything else untouched.
 * Lists are written as block lists; null writes an empty value (`key:`); undefined removes the key.
 */
export function writeFrontmatter(file: string, values: Record<string, FrontmatterValue>) {
  const src = fs.readFileSync(file, "utf8")
  const m = src.match(/^---\n([\s\S]*?)\n---\n?/)
  if (!m) throw new Error(`${rel(file)}: no frontmatter`)
  const lines = m[1].split("\n")
  for (const [key, value] of Object.entries(values)) {
    const block =
      value === undefined
        ? []
        : Array.isArray(value)
          ? value.length
            ? [`${key}:`, ...value.map((v) => `  - ${yamlScalar(v)}`)]
            : [`${key}: []`]
          : [`${key}:${value === null ? "" : " " + yamlScalar(value)}`]
    const start = lines.findIndex((l) => l === `${key}:` || l.startsWith(`${key}: `))
    if (start >= 0) {
      // the key's own line plus any indented/list continuation lines below it
      let end = start + 1
      while (end < lines.length && /^(\s+|-\s)/.test(lines[end])) end++
      lines.splice(start, end - start, ...block)
    } else if (value !== undefined) {
      const tagsIdx = lines.findIndex((l) => l.startsWith("tags:"))
      lines.splice(tagsIdx >= 0 ? tagsIdx : lines.length, 0, ...block)
    }
  }
  const out = `---\n${lines.join("\n")}\n---\n` + src.slice(m[0].length)
  if (out !== src) fs.writeFileSync(file, out)
}

// ---------------------------------------------------------------------------------------------
// Swiss pairing (pure: no file access, so it can be unit-tested)
// ---------------------------------------------------------------------------------------------

export type PairingInput = {
  /** Players to pair, best first (or already shuffled for a random round). */
  order: string[]
  /** How many times each pair of players has already met: key from pairKey(a, b). */
  meetings: Map<string, number>
  /** Byes each player has had so far. */
  byes: Map<string, number>
  /** Players who must not get the bye this round (e.g. late joiners in their first round). */
  noBye?: Set<string>
}

export type PairingResult = { pairs: [string, string][]; bye?: string; rematches: number }

/**
 * Rounds for a Swiss league, set when round 1 is drawn: enough rounds for one player to be
 * the only one left unbeaten (log2 of the player count, rounded up). 2 players: 1 round,
 * 3-4: 2, 5-8: 3, 9-16: 4, 17-32: 5.
 */
export const swissRounds = (players: number) => Math.max(1, Math.ceil(Math.log2(Math.max(players, 1))))

export const pairKey = (a: string, b: string) => [a, b].sort().join("\u0000")

/**
 * Pair players top-down, each with the closest-placed opponent they haven't played.
 * With an odd count, the bye goes to the lowest-placed player with the fewest byes so far,
 * skipping anyone in `noBye` (unless every player is in it).
 * If no rematch-free pairing exists, allows the fewest rematches possible.
 */
export function swissPair({ order, meetings, byes, noBye }: PairingInput): PairingResult {
  let pool = [...order]
  let bye: string | undefined
  if (pool.length % 2 === 1) {
    const eligible = pool.filter((p) => !noBye?.has(p))
    const candidates = eligible.length ? eligible : pool
    const fewest = Math.min(...candidates.map((p) => byes.get(p) ?? 0))
    bye = [...candidates].reverse().find((p) => (byes.get(p) ?? 0) === fewest)!
    pool = pool.filter((p) => p !== bye)
  }

  const met = (a: string, b: string) => meetings.get(pairKey(a, b)) ?? 0

  const search = (rest: string[], allowance: number): [string, string][] | null => {
    if (rest.length === 0) return []
    const [a, ...others] = rest
    for (const b of others) {
      const cost = met(a, b) > 0 ? 1 : 0
      if (cost > allowance) continue
      const tail = search(
        others.filter((p) => p !== b),
        allowance - cost,
      )
      if (tail) return [[a, b], ...tail]
    }
    return null
  }

  for (let allowance = 0; allowance <= pool.length / 2; allowance++) {
    const pairs = search(pool, allowance)
    if (pairs) {
      const rematches = pairs.filter(([a, b]) => met(a, b) > 0).length
      return { pairs, bye, rematches }
    }
  }
  throw new Error("could not pair players") // unreachable: allowance n/2 permits any pairing
}

export function shuffle<T>(items: T[], random: () => number = Math.random): T[] {
  const out = [...items]
  for (let i = out.length - 1; i > 0; i--) {
    const j = Math.floor(random() * (i + 1))
    ;[out[i], out[j]] = [out[j], out[i]]
  }
  return out
}
